/**
 * Returns the values to dump on serialize() called on.
 *
 * @return array
 */
public function __serialize(): array
{
    $data = method_exists(parent::class, '__serialize')
        ? parent::__serialize()
        : [];

    foreach (get_object_vars($this) as $name => $value) {
        if (\array_key_exists($name, $data)) {
            continue;
        }

        // The local translator may embed closures (e.g. ordinal rules)
        // which cannot be serialized. Dump only its locale.
        if ($name === 'localTranslator') {
            $data['dumpLocale'] = $this->getTranslatorLocale($this->localTranslator);

            continue;
        }

        $data[$name] = $value;
    }

    return $data;
}

/**
 * Restore the values dumped on serialize() called on.
 *
 * @param array $data
 */
public function __unserialize(array $data): void
{
    if (method_exists(parent::class, '__unserialize')) {
        parent::__unserialize($data);

        foreach (['y', 'm', 'd', 'h', 'i', 's', 'f', 'invert', 'days', 'from_string'] as $name) {
            unset($data[$name]);
        }
    }

    // Compatibility with serialized Carbon 2 intervals.
    if (isset($data['tzName'])) {
        $data['timezoneSetting'] ??= $data['tzName'];
    }

    $locale = $data['dumpLocale'] ?? null;
    unset($data['dumpLocale'], $data['tzName'], $data['localTranslator']);

    foreach ($data as $name => $value) {
        $this->$name = $value;
    }

    if ($locale !== null) {
        $this->locale($locale);
    }
}

